import React, { useState, useEffect } from 'react';
import { adminAPI, apiCall } from '../../services/apiService';
import './AllVendors.css';

const AllVendors = () => {
  const [vendors, setVendors] = useState([]);
  const [filteredVendors, setFilteredVendors] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [filters, setFilters] = useState({
    status: '',
    region: '',
    cuisine: '',
    search: ''
  });
  const [selectedVendor, setSelectedVendor] = useState(null);

  useEffect(() => {
    fetchVendors();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [vendors, filters]);

  const fetchVendors = async () => {
    setIsLoading(true);
    setError('');

    const result = await apiCall(adminAPI.getAllVendors);

    if (result.success) {
      setVendors(result.data || []);
    } else {
      setError(result.error);
    }

    setIsLoading(false);
  };

  const applyFilters = () => {
    let filtered = [...vendors];

    if (filters.status) {
      filtered = filtered.filter(vendor => vendor.status === filters.status);
    }

    if (filters.region) {
      filtered = filtered.filter(vendor => 
        vendor.operatingRegion?.toLowerCase().includes(filters.region.toLowerCase())
      );
    }

    if (filters.cuisine) {
      filtered = filtered.filter(vendor => 
        vendor.cuisineSpecialties?.toLowerCase().includes(filters.cuisine.toLowerCase())
      );
    }

    if (filters.search) {
      const searchLower = filters.search.toLowerCase();
      filtered = filtered.filter(vendor => 
        vendor.name?.toLowerCase().includes(searchLower) ||
        vendor.email?.toLowerCase().includes(searchLower) ||
        vendor.contactNumber?.toLowerCase().includes(searchLower)
      );
    }

    // Sort by most recent first
    filtered.sort((a, b) => new Date(b.createdAt || b.registeredAt) - new Date(a.createdAt || a.registeredAt));
    setFilteredVendors(filtered);
  };

  const handleFilterChange = (filterType, value) => {
    setFilters(prev => ({
      ...prev,
      [filterType]: value
    }));
  };

  const clearFilters = () => {
    setFilters({
      status: '',
      region: '',
      cuisine: '',
      search: ''
    });
  };

  const handleVendorAction = async (vendorId, action) => {
    setError('');
    setSuccess('');

    const result = await apiCall(adminAPI.updateVendorStatus, {
      vendorId,
      action
    });

    if (result.success) {
      setSuccess(`Vendor ${action.toLowerCase()} successfully!`);
      fetchVendors(); // Refresh the list
      setSelectedVendor(null);
    } else {
      setError(result.error);
    }
  };

  const getVendorStats = () => {
    const stats = {
      total: vendors.length,
      active: vendors.filter(v => v.status === 'ACTIVE' || v.status === 'APPROVED').length,
      pending: vendors.filter(v => v.status === 'PENDING' || v.status === 'UNDER_REVIEW').length,
      suspended: vendors.filter(v => v.status === 'SUSPENDED').length,
      rejected: vendors.filter(v => v.status === 'REJECTED').length
    };
    return stats;
  };

  const getUniqueValues = (field) => {
    const values = vendors
      .map(vendor => vendor[field])
      .filter(value => value)
      .flatMap(value => typeof value === 'string' ? value.split(',').map(item => item.trim()) : [value])
      .filter(item => item);
    
    return [...new Set(values)];
  };

  const getUniqueStatuses = () => {
    return [...new Set(vendors.map(vendor => vendor.status).filter(Boolean))];
  };

  if (isLoading) {
    return (
      <div className="loading">
        <div className="loading-spinner"></div>
        Loading vendors...
      </div>
    );
  }

  const stats = getVendorStats();

  return (
    <div className="all-vendors">
      <div className="page-header">
        <div className="container">
          <h1>All Vendors</h1>
          <p>Manage and oversee all registered food truck vendors</p>
        </div>
      </div>

      <div className="container">
        {error && (
          <div className="alert alert-error">
            {error}
          </div>
        )}

        {success && (
          <div className="alert alert-success">
            {success}
          </div>
        )}

        {/* Vendors Summary */}
        <div className="vendors-summary">
          <div className="summary-stats">
            <div className="stat-item">
              <div className="stat-number">{stats.total}</div>
              <div className="stat-label">Total Vendors</div>
            </div>
            
            <div className="stat-item">
              <div className="stat-number">{stats.active}</div>
              <div className="stat-label">Active</div>
            </div>
            
            <div className="stat-item">
              <div className="stat-number">{stats.pending}</div>
              <div className="stat-label">Pending</div>
            </div>

            <div className="stat-item">
              <div className="stat-number">{stats.suspended}</div>
              <div className="stat-label">Suspended</div>
            </div>

            <div className="stat-item">
              <div className="stat-number">{stats.rejected}</div>
              <div className="stat-label">Rejected</div>
            </div>
          </div>
        </div>

        {/* Filters Section */}
        <div className="filters-section">
          <div className="filters-header">
            <h2>Filter Vendors</h2>
            <button 
              onClick={clearFilters} 
              className="btn btn-secondary btn-sm"
              disabled={!filters.status && !filters.region && !filters.cuisine && !filters.search}
            >
              Clear Filters
            </button>
          </div>

          <div className="filters-grid">
            <div className="filter-group">
              <label className="filter-label">Search</label>
              <input
                type="text"
                value={filters.search}
                onChange={(e) => handleFilterChange('search', e.target.value)}
                placeholder="Search by name, email, or contact..."
                className="form-control filter-input"
              />
            </div>

            <div className="filter-group">
              <label className="filter-label">Status</label>
              <select
                value={filters.status}
                onChange={(e) => handleFilterChange('status', e.target.value)}
                className="form-control filter-select"
              >
                <option value="">All Statuses</option>
                {getUniqueStatuses().map(status => (
                  <option key={status} value={status}>{status.replace('_', ' ')}</option>
                ))}
              </select>
            </div>

            <div className="filter-group">
              <label className="filter-label">Region</label>
              <select
                value={filters.region}
                onChange={(e) => handleFilterChange('region', e.target.value)}
                className="form-control filter-select"
              >
                <option value="">All Regions</option>
                {getUniqueValues('operatingRegion').map(region => (
                  <option key={region} value={region}>{region}</option>
                ))}
              </select>
            </div>

            <div className="filter-group">
              <label className="filter-label">Cuisine Type</label>
              <select
                value={filters.cuisine}
                onChange={(e) => handleFilterChange('cuisine', e.target.value)}
                className="form-control filter-select"
              >
                <option value="">All Cuisines</option>
                {getUniqueValues('cuisineSpecialties').map(cuisine => (
                  <option key={cuisine} value={cuisine}>{cuisine}</option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* Results Summary */}
        <div className="results-summary">
          <p>
            Showing {filteredVendors.length} of {vendors.length} vendors
            {(filters.status || filters.region || filters.cuisine || filters.search) && (
              <span className="filter-summary">
                {filters.search && ` matching "${filters.search}"`}
                {filters.status && ` with status: ${filters.status.replace('_', ' ')}`}
                {filters.region && ` in ${filters.region}`}
                {filters.cuisine && ` serving ${filters.cuisine}`}
              </span>
            )}
          </p>
        </div>

        {/* Vendors Grid */}
        {filteredVendors.length === 0 ? (
          <div className="no-vendors">
            <div className="no-vendors-icon">🏪</div>
            <h3>No Vendors Found</h3>
            <p>
              {vendors.length === 0 
                ? "No vendors are currently registered."
                : "Try adjusting your filters to see more results."
              }
            </p>
            {(filters.status || filters.region || filters.cuisine || filters.search) && (
              <button onClick={clearFilters} className="btn btn-primary">
                Show All Vendors
              </button>
            )}
          </div>
        ) : (
          <div className="vendors-grid">
            {filteredVendors.map(vendor => (
              <AdminVendorCard
                key={vendor.id}
                vendor={vendor}
                onAction={handleVendorAction}
                onSelect={setSelectedVendor}
              />
            ))}
          </div>
        )}

        {/* Vendor Details Modal */}
        {selectedVendor && (
          <VendorModal
            vendor={selectedVendor}
            onClose={() => setSelectedVendor(null)}
            onAction={handleVendorAction}
          />
        )}
      </div>
    </div>
  );
};

const AdminVendorCard = ({ vendor, onAction, onSelect }) => {
  const getStatusInfo = (status) => {
    const statusMap = {
      ACTIVE: { label: 'Active', color: 'active', description: 'Vendor is active and operating' },
      PENDING: { label: 'Pending', color: 'pending', description: 'Awaiting approval', actionable: true },
      APPROVED: { label: 'Approved', color: 'approved', description: 'Vendor approved and can operate' },
      SUSPENDED: { label: 'Suspended', color: 'suspended', description: 'Vendor temporarily suspended' },
      REJECTED: { label: 'Rejected', color: 'rejected', description: 'Vendor application rejected' },
      UNDER_REVIEW: { label: 'Under Review', color: 'review', description: 'Vendor under review', actionable: true }
    };
    return statusMap[status] || { label: status || 'Unknown', color: 'pending', description: 'Status unknown' };
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Not available';
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  const statusInfo = getStatusInfo(vendor.status);
  const canTakeAction = statusInfo.actionable;

  return (
    <div className="admin-vendor-card">
      <div className="vendor-header">
        <div className="vendor-id">
          <h3>{vendor.name}</h3>
          <span className={`status-badge ${statusInfo.color}`}>
            {statusInfo.label}
          </span>
        </div>
        <div className="vendor-actions">
          <button
            onClick={() => onSelect(vendor)}
            className="btn btn-secondary btn-sm"
          >
            View Details
          </button>
          {canTakeAction && (
            <>
              <button
                onClick={() => onAction(vendor.id, 'APPROVED')}
                className="btn btn-success btn-sm"
              >
                Approve
              </button>
              <button
                onClick={() => onAction(vendor.id, 'REJECTED')}
                className="btn btn-danger btn-sm"
              >
                Reject
              </button>
            </>
          )}
        </div>
      </div>

      <div className="vendor-body">
        <div className="vendor-contact">
          <div className="contact-item">
            <strong>Email:</strong> {vendor.email}
          </div>
          {vendor.contactNumber && (
            <div className="contact-item">
              <strong>Contact:</strong> {vendor.contactNumber}
            </div>
          )}
        </div>

        <div className="vendor-info">
          {vendor.operatingRegion && (
            <div className="info-item">
              <strong>Region:</strong> {vendor.operatingRegion}
            </div>
          )}

          {vendor.cuisineSpecialties && (
            <div className="info-item">
              <strong>Cuisines:</strong>
              <div className="cuisine-tags">
                {vendor.cuisineSpecialties.split(',').slice(0, 3).map((cuisine, index) => (
                  <span key={index} className="cuisine-tag">
                    {cuisine.trim()}
                  </span>
                ))}
                {vendor.cuisineSpecialties.split(',').length > 3 && (
                  <span className="cuisine-tag more">
                    +{vendor.cuisineSpecialties.split(',').length - 3} more
                  </span>
                )}
              </div>
            </div>
          )}

          <div className="info-item">
            <strong>Registered:</strong> {formatDate(vendor.createdAt || vendor.registeredAt)}
          </div>
        </div>

        <div className="vendor-status">
          <div className="status-description">
            {statusInfo.description}
          </div>
        </div>

        {vendor.description && (
          <div className="vendor-description">
            <strong>About:</strong>
            <p>{vendor.description.length > 100 ? vendor.description.substring(0, 100) + '...' : vendor.description}</p>
          </div>
        )}
      </div>
    </div>
  );
};

const VendorModal = ({ vendor, onClose, onAction }) => {
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleAction = async (action) => {
    setIsSubmitting(true);
    await onAction(vendor.id, action);
    setIsSubmitting(false);
  };

  const getStatusInfo = (status) => {
    const statusMap = {
      ACTIVE: { label: 'Active', color: 'active' },
      PENDING: { label: 'Pending', color: 'pending' },
      APPROVED: { label: 'Approved', color: 'approved' },
      SUSPENDED: { label: 'Suspended', color: 'suspended' },
      REJECTED: { label: 'Rejected', color: 'rejected' },
      UNDER_REVIEW: { label: 'Under Review', color: 'review' }
    };
    return statusMap[status] || { label: status || 'Unknown', color: 'pending' };
  };

  const statusInfo = getStatusInfo(vendor.status);

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>{vendor.name}</h2>
          <button onClick={onClose} className="modal-close">×</button>
        </div>

        <div className="modal-body">
          <div className="vendor-details">
            <div className="detail-section">
              <h3>Vendor Information</h3>
              <div className="detail-grid">
                <div className="detail-item">
                  <span className="detail-label">Name:</span>
                  <span className="detail-value">{vendor.name}</span>
                </div>
                <div className="detail-item">
                  <span className="detail-label">Status:</span>
                  <span className={`detail-value status-badge ${statusInfo.color}`}>
                    {statusInfo.label}
                  </span>
                </div>
                <div className="detail-item">
                  <span className="detail-label">Email:</span>
                  <span className="detail-value">{vendor.email}</span>
                </div>
                {vendor.contactNumber && (
                  <div className="detail-item">
                    <span className="detail-label">Contact:</span>
                    <span className="detail-value">{vendor.contactNumber}</span>
                  </div>
                )}
                {vendor.operatingRegion && (
                  <div className="detail-item">
                    <span className="detail-label">Operating Region:</span>
                    <span className="detail-value">{vendor.operatingRegion}</span>
                  </div>
                )}
                <div className="detail-item">
                  <span className="detail-label">Registered:</span>
                  <span className="detail-value">
                    {new Date(vendor.createdAt || vendor.registeredAt).toLocaleString()}
                  </span>
                </div>
              </div>
            </div>

            {vendor.cuisineSpecialties && (
              <div className="detail-section">
                <h3>Cuisine Specialties</h3>
                <div className="cuisine-tags">
                  {vendor.cuisineSpecialties.split(',').map((cuisine, index) => (
                    <span key={index} className="cuisine-tag">
                      {cuisine.trim()}
                    </span>
                  ))}
                </div>
              </div>
            )}

            {vendor.description && (
              <div className="detail-section">
                <h3>Description</h3>
                <p>{vendor.description}</p>
              </div>
            )}

            {vendor.profileComplete !== undefined && (
              <div className="detail-section">
                <h3>Profile Status</h3>
                <p>
                  <strong>Profile Complete:</strong> {vendor.profileComplete ? 'Yes' : 'No'}
                </p>
              </div>
            )}

            {vendor.applications && vendor.applications.length > 0 && (
              <div className="detail-section">
                <h3>Applications History</h3>
                <div className="applications-summary">
                  <p>Total Applications: {vendor.applications.length}</p>
                  <p>
                    Recent Status: {vendor.applications[0]?.status?.replace('_', ' ') || 'None'}
                  </p>
                </div>
              </div>
            )}

            {vendor.lastLoginAt && (
              <div className="detail-section">
                <h3>Activity</h3>
                <p>
                  <strong>Last Login:</strong> {new Date(vendor.lastLoginAt).toLocaleString()}
                </p>
              </div>
            )}
          </div>
        </div>

        <div className="modal-footer">
          <button onClick={onClose} className="btn btn-secondary">
            Close
          </button>
          {vendor.status === 'PENDING' || vendor.status === 'UNDER_REVIEW' ? (
            <>
              <button
                onClick={() => handleAction('APPROVED')}
                className="btn btn-success"
                disabled={isSubmitting}
              >
                {isSubmitting ? 'Processing...' : 'Approve Vendor'}
              </button>
              <button
                onClick={() => handleAction('REJECTED')}
                className="btn btn-danger"
                disabled={isSubmitting}
              >
                {isSubmitting ? 'Processing...' : 'Reject Vendor'}
              </button>
            </>
          ) : vendor.status === 'ACTIVE' || vendor.status === 'APPROVED' ? (
            <button
              onClick={() => handleAction('SUSPENDED')}
              className="btn btn-warning"
              disabled={isSubmitting}
            >
              {isSubmitting ? 'Processing...' : 'Suspend Vendor'}
            </button>
          ) : vendor.status === 'SUSPENDED' ? (
            <button
              onClick={() => handleAction('ACTIVE')}
              className="btn btn-success"
              disabled={isSubmitting}
            >
              {isSubmitting ? 'Processing...' : 'Reactivate Vendor'}
            </button>
          ) : null}
        </div>
      </div>
    </div>
  );
};

export default AllVendors;
